gWW(){return"\u062c\u06c6\u0631\u06cc \u0646\u0648\u06ce"},
gWZ(){return"\u0647\u06ce\u0634\u062a\u0627 \u0647\u06cc\u0686 \u062c\u06c6\u0631\u06ce\u06a9\u06cc \u0646\u0631\u062e \u0646\u06cc\u06cc\u06d5."},
